using System.Security.Claims;using AuthService.DTOs;using AuthService.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace AuthService.Controllers;[ApiController][Route("api/auth")]public class AuthController(IAuthService s):ControllerBase{[HttpPost("register")]public async Task<IActionResult>Register(RegisterRequest r,CancellationToken c)=>Ok(await s.Register(r,c));[HttpPost("login")]public async Task<IActionResult>Login(LoginRequest r,CancellationToken c)=>Ok(await s.Login(r,c));[Authorize][HttpGet("me")]public IActionResult Me()=>Ok(new{UserId=User.FindFirstValue(ClaimTypes.NameIdentifier),Username=User.Identity?.Name,Role=User.FindFirstValue(ClaimTypes.Role)});}